UPDATE duty_schedule
staff_id = #{staffId}, staff_type = #{staffType}, duty_date = #{dutyDate}, slot_id = #{slotId}, room_id = #{roomId}, capacity = #{capacity}, status = #{status}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT ds.id, ds.staff_id, sp.user_id, su.real_name AS staff_name, ds.staff_type, ds.duty_date, ds.slot_id, ts.slot_name, ts.start_time, ts.end_time, ds.room_id, cr.room_name, ds.capacity, ds.reserved_count, (ds.capacity - ds.reserved_count) AS remaining, ds.status FROM duty_schedule ds LEFT JOIN staff_profile sp ON ds.staff_id = sp.id LEFT JOIN sys_user su ON sp.user_id = su.id LEFT JOIN time_slot ts ON ds.slot_id = ts.id LEFT JOIN counseling_room cr ON ds.room_id = cr.id WHERE 1=1
AND ds.staff_type = #{staffType}
AND ds.staff_id = #{staffId}
AND ds.duty_date >= #{startDate}
AND ds.duty_date <= #{endDate}
AND ds.status = #{status}
ORDER BY ds.duty_date DESC, ts.start_time ASC

SELECT COUNT(*) FROM duty_schedule ds
WHERE 1=1

    AND ds.staff_type = #{staffType}


    AND ds.staff_id = #{staffId}


    AND ds.duty_date >= #{startDate}


    AND ds.duty_date <= #{endDate}


    AND ds.status = #{status}

SELECT COUNT(*) FROM duty_schedule
WHERE staff_id = #{staffId}
  AND duty_date = #{dutyDate}
  AND slot_id = #{slotId}

      AND id != #{excludeId}

SELECT CASE WHEN #{newCapacity} >= reserved_count THEN true ELSE false END
FROM duty_schedule
WHERE id = #{id}
